test('a second slot keeps its own row status while the first is retried only by its starter', () => {
  const item = detail(); item.publication = 'notStarted'; item.capabilities.upload = true;
  const recovery = { operationId: '30000000-0000-4000-8000-000000000003', expectedRevision: 1, kind: 'upload' as const, startedByMe: false };
  item.assets = [{ slotId, state: 'unknown', byteLength: 100, sha256: 'a'.repeat(64), contentType: 'audio/mpeg', tags: null, recovery }, { slotId: slotTwo, state: 'ready', byteLength: 200, sha256: 'b'.repeat(64), contentType: 'audio/mpeg', tags: null, recovery: { ...recovery, operationId: '30000000-0000-4000-8000-000000000004' } }];
  adminWorkspace.retain(`files:${item.id}`, { [slotId]: new File(['a'.repeat(100)], '01 First.mp3') }, adminWorkspace.capture());
  const view = mount(item), row = () => screen.getByText('Synthetic Album/01 First.mp3').closest('li')!;
  expect(within(row()).getByText('Upload outcome unknown')).toBeVisible(); expect(within(row()).queryByRole('button', { name: 'Retry upload' })).not.toBeInTheDocument();
  expect(within(row()).getByRole('button', { name: 'Check again' })).toBeEnabled();
  expect(within(screen.getByText('Synthetic Album/02 Second.mp3').closest('li')!).getByText('Ready')).toBeVisible();
  act(() => view.rerender(view.element({ ...item, assets: [{ ...item.assets[0], recovery: { ...recovery, startedByMe: true } }, item.assets[1]] })));
  expect(within(row()).getByRole('button', { name: 'Retry upload' })).toBeEnabled();
});
