  mount({ ...item, selectedCoverSlotId: embedded, assets: [{ slotId: embedded, state: 'ready', byteLength: 100, sha256: 'c'.repeat(64), contentType: 'image/jpeg', tags: null, recovery: null }] }, new AdminMutation(), 'publication');
